u16 ReplayBrowserScene::advance(const MenuInput& input,ReplayBrowserSignals& signals){signals.render_replays();signals.present_replays();const i32 vertical=input.vertical[0]==-1||input.vertical[1]==-1?-1:input.vertical[0]==1||input.vertical[1]==1?1:0,horizontal=input.horizontal[0]==-1||input.horizontal[1]==-1?-1:input.horizontal[0]==1||input.horizontal[1]==1?1:0;if(!roundSelection){if(vertical){signals.sound(39);selected=i16(selected+vertical);selected=std::max<i16>(0,selected);if(vertical>0&&selected>=i16(entries.size()))selected=i16(entries.size())-1;}if(horizontal){signals.sound(39);selected=i16(selected+horizontal*10);selected=std::max<i16>(0,selected);if(horizontal>0&&selected>=i16(entries.size()))selected=i16(entries.size())-1;}}else if(vertical&&!entries.empty()){signals.sound(39);round=i16(round+vertical);const i32 count=i8(entries[selected].replay.header[14]);if(round<0)round=i16(count-1);if(round>=count)round=0;}if(alpha!=255)alpha=u8(alpha+25);if((input.confirm[0]==1||input.confirm[1]==1)&&!entries.empty()){signals.sound(45);const auto& h=entries[selected].replay.header;if(i8(h[13])<1){signals.start_replay(selected,0);signals.fade_music(-10000,-60,1,0);return 0x2201;}if(roundSelection){signals.start_replay(selected,u8(round));signals.fade_music(-10000,-60,1,0);return 0x2201;}if(i8(h[14])<2){signals.start_replay(selected,0);signals.fade_music(-10000,-60,1,0);return 0x2201;}roundSelection=true;round=0;}if(input.cancel[0]==1||input.cancel[1]==1||input.escape){signals.sound(40);if(!roundSelection)return 0x2202;roundSelection=false;}return 5;}
void ReplayBrowserScene::render(ImageRenderer& images)const{images.graphics.depth(DepthMode::Disabled);images.blend(SpriteBlend::Alpha);MenuDrawing::region(images,0,{0,0,640,480},0,0,640,480);MenuDrawing::region(images,1,{192,96,512,128},160,10,480,42);MenuDrawing::region(images,1,{0,0,512,20},64,50,576,70);const i32 base=selected/10*10;const u32 count=base/10==i32(entries.size()/10)?u32(entries.size()%10):10;for(u32 i=0;i<count&&base+i<entries.size();i++){const auto& entry=entries[base+i];const auto& h=entry.replay.header;const u32 a=base+i==selected?alpha:alpha/2,color=a<<24|0xffffff;const float y=float(i*24+80);MenuDrawing::replay_file(images,50,y,color,entry.filename);std::array<u8,8> name;std::copy_n(h.data(),8,name.data());MenuDrawing::name(images,160,y,color,name);MenuDrawing::digits(images,330,y,color,i8(h[8]),2);MenuDrawing::region(images,2,{228,40,247,60},325,y,344,y+20,color);MenuDrawing::digits(images,370,y,color,i8(h[9]),2);if(h[13]==0){const i32 t=entry.otherCharacter*20+20;MenuDrawing::region(images,1,{0,t,100,t+20},416,y+14,516,y+28,a<<24|0xc0c0c0);}const i32 t=i8(h[10])*20+20,m=i8(h[13])*20+20;MenuDrawing::region(images,1,{0,t,100,t+20},380,y,480,y+20,color);MenuDrawing::region(images,1,{100,m,180,m+20},500,y,580,y+20,color);}if(roundSelection&&!entries.empty())for(i32 i=0;i<i8(entries[selected].replay.header[14]);i++){auto q=rectangle_quad(40,float(i*20+320),140,float(i*20+337));if(i>4)translate_quad(q,120,-100,0);images.quad(1,q,{100,i*17+224,200,i*17+241},u32(i==round?255:128)<<24|0xffffff);}}
